fn is_palindrome(text: Vec<char>) -> bool {
    let mut left = 0;
    let mut right = text.len().saturating_sub(1); // Handle empty vector case

    while left < right {
        // Move left pointer to the next valid character
        while left < right && !text[left].is_ascii_alphabetic() {
            left += 1;
        }
        // Move right pointer to the previous valid character
        while left < right && !text[right].is_ascii_alphabetic() {
            right = right.saturating_sub(1);
        }

        // Compare characters in a case-insensitive manner
        if left < right {
            let left_char = text[left].to_ascii_lowercase();
            let right_char = text[right].to_ascii_lowercase();
            if left_char != right_char {
                return false;
            }
        }

        left += 1;
        right = right.saturating_sub(1);
    }

    true
}